// src/features/Sales/pages/CashFlowManagement.jsx
import React, { useState } from 'react';
import {
  Container,
  Typography,
  Divider,
  Box,
  Tabs,
  Tab,
  Paper,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Chip,
  Button
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';

// Función local para formatear moneda
const formatCurrency = (value) => {
  return new Intl.NumberFormat('es-MX', {
    style: 'currency',
    currency: 'MXN'
  }).format(value || 0);
};

// Función local para formatear fecha
const formatDate = (dateString) => {
  const date = new Date(dateString);
  return date.toLocaleDateString('es-MX', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
};

const CashFlowManagement = () => {
  const [tabValue, setTabValue] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  // Datos de ejemplo para el dashboard
  const cashFlowData = {
    currentBalance: 15000,
    incomingFunds: 5000,
    outgoingFunds: 3000,
    projectedBalance: 17000
  };

  // Datos de ejemplo para proyecciones
  const projectionData = {
    inflows: [
      { period: 'Mayo 2023', amount: 15000 },
      { period: 'Junio 2023', amount: 18000 },
      { period: 'Julio 2023', amount: 20000 }
    ],
    outflows: [
      { period: 'Mayo 2023', amount: 12000 },
      { period: 'Junio 2023', amount: 13000 },
      { period: 'Julio 2023', amount: 15000 }
    ],
    netFlow: [
      { period: 'Mayo 2023', amount: 3000 },
      { period: 'Junio 2023', amount: 5000 },
      { period: 'Julio 2023', amount: 5000 }
    ],
    cumulativeFlow: [
      { period: 'Mayo 2023', amount: 3000 },
      { period: 'Junio 2023', amount: 8000 },
      { period: 'Julio 2023', amount: 13000 }
    ]
  };

  // Datos de ejemplo para gastos
  const expenses = [
    { id: 1, date: '2023-05-01', description: 'Renta de oficina', category: 'Renta', amount: 5000, paid: true },
    { id: 2, date: '2023-05-05', description: 'Servicios de internet', category: 'Servicios', amount: 800, paid: true },
    { id: 3, date: '2023-05-10', description: 'Materiales de oficina', category: 'Suministros', amount: 1200, paid: false },
    { id: 4, date: '2023-05-15', description: 'Pago a proveedores', category: 'Proveedores', amount: 3500, paid: false },
    { id: 5, date: '2023-05-20', description: 'Servicios de agua', category: 'Servicios', amount: 300, paid: true }
  ];

  // Componente de Dashboard
  const CashFlowDashboard = () => (
    <Paper sx={{ p: 2, width: '100%' }}>
      <Typography variant="h6" gutterBottom>
        Flujo de Efectivo
      </Typography>
      
      <Grid container spacing={3}>
        <Grid item xs={12} md={6} lg={3}>
          <Box sx={{ p: 2, bgcolor: 'info.light', borderRadius: 1 }}>
            <Typography variant="body2" color="text.secondary">
              Saldo Actual
            </Typography>
            <Typography variant="h5">
              {formatCurrency(cashFlowData.currentBalance)}
            </Typography>
          </Box>
        </Grid>
        
        <Grid item xs={12} md={6} lg={3}>
          <Box sx={{ p: 2, bgcolor: 'success.light', borderRadius: 1 }}>
            <Typography variant="body2" color="text.secondary">
              Ingresos Pendientes
            </Typography>
            <Typography variant="h5">
              {formatCurrency(cashFlowData.incomingFunds)}
            </Typography>
          </Box>
        </Grid>
        
        <Grid item xs={12} md={6} lg={3}>
          <Box sx={{ p: 2, bgcolor: 'error.light', borderRadius: 1 }}>
            <Typography variant="body2" color="text.secondary">
              Gastos Pendientes
            </Typography>
            <Typography variant="h5">
              {formatCurrency(cashFlowData.outgoingFunds)}
            </Typography>
          </Box>
        </Grid>
        
        <Grid item xs={12} md={6} lg={3}>
          <Box sx={{ p: 2, bgcolor: 'warning.light', borderRadius: 1 }}>
            <Typography variant="body2" color="text.secondary">
              Saldo Proyectado
            </Typography>
            <Typography variant="h5">
              {formatCurrency(cashFlowData.projectedBalance)}
            </Typography>
          </Box>
        </Grid>
      </Grid>
      
      <Box sx={{ height: 300, bgcolor: 'background.paper', p: 2, borderRadius: 1, mt: 3 }}>
        <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', pt: 10 }}>
          Aquí se mostrará el gráfico de flujo de efectivo
        </Typography>
      </Box>
    </Paper>
  );

  // Componente de Proyecciones
  const CashFlowProjections = () => (
    <Paper sx={{ p: 2, width: '100%' }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h6">Proyecciones de Flujo de Efectivo</Typography>
        
        <Box sx={{ display: 'flex', gap: 2 }}>
          <FormControl sx={{ minWidth: 150 }} size="small">
            <InputLabel id="period-select-label">Periodo</InputLabel>
            <Select
              labelId="period-select-label"
              value="month"
              label="Periodo"
            >
              <MenuItem value="week">Semanal</MenuItem>
              <MenuItem value="month">Mensual</MenuItem>
              <MenuItem value="quarter">Trimestral</MenuItem>
            </Select>
          </FormControl>
          
          <FormControl sx={{ minWidth: 150 }} size="small">
            <InputLabel id="months-select-label">Duración</InputLabel>
            <Select
              labelId="months-select-label"
              value={3}
              label="Duración"
            >
              <MenuItem value={3}>3 meses</MenuItem>
              <MenuItem value={6}>6 meses</MenuItem>
              <MenuItem value={12}>12 meses</MenuItem>
            </Select>
          </FormControl>
        </Box>
      </Box>
      
      <Box sx={{ height: 300, bgcolor: 'background.paper', p: 2, borderRadius: 1, mb: 3 }}>
        <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', pt: 10 }}>
          Aquí se mostrará el gráfico de proyecciones
        </Typography>
      </Box>
      
      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Typography variant="subtitle1" gutterBottom>
            Ingresos Proyectados
          </Typography>
          <Box sx={{ bgcolor: 'success.light', p: 2, borderRadius: 1 }}>
            {projectionData.inflows.map((item, index) => (
              <Box key={index} sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                <Typography variant="body2">{item.period}</Typography>
                <Typography variant="body2" fontWeight="bold">
                  {formatCurrency(item.amount)}
                </Typography>
              </Box>
            ))}
          </Box>
        </Grid>
        
        <Grid item xs={12} md={6}>
          <Typography variant="subtitle1" gutterBottom>
            Gastos Proyectados
          </Typography>
          <Box sx={{ bgcolor: 'error.light', p: 2, borderRadius: 1 }}>
            {projectionData.outflows.map((item, index) => (
              <Box key={index} sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                <Typography variant="body2">{item.period}</Typography>
                <Typography variant="body2" fontWeight="bold">
                  {formatCurrency(item.amount)}
                </Typography>
              </Box>
            ))}
          </Box>
        </Grid>
        
        <Grid item xs={12}>
          <Typography variant="subtitle1" gutterBottom>
            Flujo Neto Acumulado
          </Typography>
          <Box sx={{ bgcolor: 'background.paper', p: 2, borderRadius: 1 }}>
            {projectionData.cumulativeFlow.map((item, index) => (
              <Box key={index} sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                <Typography variant="body2">{item.period}</Typography>
                <Typography 
                  variant="body2" 
                  fontWeight="bold"
                  color={item.amount >= 0 ? 'success.main' : 'error.main'}
                >
                  {formatCurrency(item.amount)}
                </Typography>
              </Box>
            ))}
          </Box>
        </Grid>
      </Grid>
    </Paper>
  );

  // Componente de Seguimiento de Gastos
  const ExpenseTracking = () => (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">Seguimiento de Gastos</Typography>
        
        <Button
          variant="contained"
          color="primary"
          startIcon={<AddIcon />}
          size="small"
        >
          Nuevo Gasto
        </Button>
      </Box>
      
      <TableContainer>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Fecha</TableCell>
              <TableCell>Descripción</TableCell>
              <TableCell>Categoría</TableCell>
              <TableCell align="right">Monto</TableCell>
              <TableCell align="center">Estado</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {expenses.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((expense) => (
              <TableRow key={expense.id}>
                <TableCell>{formatDate(expense.date)}</TableCell>
                <TableCell>{expense.description}</TableCell>
                <TableCell>{expense.category}</TableCell>
                <TableCell align="right">{formatCurrency(expense.amount)}</TableCell>
                <TableCell align="center">
                  <Chip 
                    label={expense.paid ? 'Pagado' : 'Pendiente'}
                    color={expense.paid ? 'success' : 'warning'}
                    size="small"
                  />
                </TableCell>
              </TableRow>
            ))}
            {expenses.length === 0 && (
              <TableRow>
                <TableCell colSpan={5} align="center">
                  No hay gastos registrados
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
      
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={expenses.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
      />
    </Box>
  );

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Gestión de Flujo de Efectivo
      </Typography>
      <Divider sx={{ mb: 4 }} />

      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={tabValue} onChange={handleTabChange} aria-label="cash flow tabs">
          <Tab label="Resumen" />
          <Tab label="Proyecciones" />
          <Tab label="Seguimiento de Gastos" />
        </Tabs>
      </Box>

      <Box sx={{ mt: 2 }}>
        {tabValue === 0 && <CashFlowDashboard />}
        {tabValue === 1 && <CashFlowProjections />}
        {tabValue === 2 && <ExpenseTracking />}
      </Box>
    </Container>
  );
};

export default CashFlowManagement;